package org.strongswan.android.rookstride;
import android.content.*;import android.os.*;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import org.strongswan.android.ui.RookstrideActivity;import org.strongswan.android.rookstride.engine.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.Files;import java.util.*;
import static org.junit.Assert.*;import static org.junit.Assume.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.assertion.ViewAssertions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;
/** Opt-in owned disposable VM only; credentials never enter source or result files. */
@RunWith(AndroidJUnit4.class) public class NativeModulesIntegrationTest {
 Context c;JSONObject fixture;Gateway node;
 @Before public void setup()throws Exception{c=InstrumentationRegistry.getInstrumentation().getTargetContext();File file=new File(c.getFilesDir(),"native-install-test.json");assumeTrue(file.isFile());fixture=new JSONObject(new String(Files.readAllBytes(file.toPath()),"UTF-8"));assumeTrue(fixture.optBoolean("disposable"));node=new Gateway(new JSONObject(fixture.getJSONObject("admin").toString()));node.set("id",UUID.randomUUID().toString());node.set("protocol","awg");node.set("name","Disposable AWG");node.data.put("remember",true);node.data.put("vpnPortAuto",true);NativeVpn.disconnectAll(c);waitOff();new File(c.getNoBackupFilesDir(),"app-routing.json").delete();}
 void waitOff()throws Exception{long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){boolean active=false;for(String p:new String[]{"awg","xray","openvpn"})if(NativeVpn.isActive(NativeVpn.status(c,p).state))active=true;if(!active)return;Thread.sleep(150);}fail("VPN did not stop");}
 JSONObject api(String action,Object... pairs)throws Exception{JSONObject req=new JSONObject().put("protocol","awg").put("action",action);for(int i=0;i<pairs.length;i+=2)req.put((String)pairs[i],pairs[i+1]);try(Ssh ssh=new Ssh(node);InputStream bundle=c.getAssets().open("single_bundle.zip")){return ssh.single(bundle,req);}}
 Object invoke(Object a,String name,Class<?>[] types,Object...args)throws Exception{Method m=a.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(a,args);}
 void act(ActivityScenario<RookstrideActivity> screen,String name){screen.onActivity(a->{try{invoke(a,name,new Class<?>[]{Gateway.class},node);}catch(Exception e){throw new AssertionError(e);}});}
 @Test public void administratorWorksWithoutAnActiveVpn()throws Exception{
  JSONObject status=api("status");assertTrue(status.getBoolean("running"));assertTrue(status.getBoolean("monitoring_available"));
  String login="offline-admin-"+UUID.randomUUID().toString().substring(0,8);api("add-user","login",login);
  try{JSONObject profile=api("profile","login",login);assertTrue(profile.getString("content").contains("[Peer]"));assertTrue(api("status").getJSONArray("users").toString().contains(login));JSONObject filter=api("adguard");assertTrue(filter.has("queries"));assertTrue(filter.has("filters"));boolean enabled=filter.getBoolean("protection_enabled");try{assertFalse(api("adguard","enabled",false).getBoolean("protection_enabled"));}finally{assertEquals(enabled,api("adguard","enabled",enabled).getBoolean("protection_enabled"));}}
  finally{api("remove-user","login",login);}waitOff();
  Files.write(new File(c.getFilesDir(),"offline-admin-result.json").toPath(),new JSONObject().put("disconnected_ssh_add_export_remove",true).put("adguard_without_extra_password",true).toString().getBytes("UTF-8"));
 }
 @Test public void appRoutingActuallyIncludesAndExcludesProbe()throws Exception{
  JSONObject health=api("status");String login=health.getJSONArray("users").getJSONObject(0).getString("login");String content=api("profile","login",login).getString("content");
  // Existing Linux fixture profiles advertise the Docker bridge; phone transport uses the owned host forward.
  content=content.replaceAll("(?m)^Endpoint = .*", "Endpoint = 10.0.2.2:51820");new NativeProfileStore(c).save(node.get("id"),"awg",node.get("name"),content);
  Method probe=NativeEngineIntegrationTest.class.getDeclaredMethod("foreignProbe",Context.class,String.class,boolean.class);probe.setAccessible(true);JSONArray result=new JSONArray();
  try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){
   for(String[] policy:new String[][]{{"only","io.rookstride.probe","yes"},{"only","com.android.settings","no"},{"exclude","io.rookstride.probe","no"},{"exclude","com.android.settings","yes"},{"all","","yes"}}){
    AppRouting.save(c,new AppRouting.Policy(policy[0],policy[1].isEmpty()?Collections.emptyList():Arrays.asList(policy[1])));NativeVpn.start(c,"awg",node.get("id"));long deadline=SystemClock.elapsedRealtime()+90000;while(SystemClock.elapsedRealtime()<deadline&&!NativeVpn.status(c,"awg").state.equals("connected")&&!NativeVpn.status(c,"awg").state.equals("failed"))Thread.sleep(300);assertEquals("connected",NativeVpn.status(c,"awg").state);
    boolean expected=policy[2].equals("yes");JSONObject traffic=(JSONObject)probe.invoke(new NativeEngineIntegrationTest(),c,fixture.getString("canaryUrl"),!expected);if(!expected)assertTrue(traffic.getBoolean("canaryUnavailable"));assertEquals("App route transport",expected,traffic.getBoolean("vpnTransport"));assertEquals("VPN-only canary attribution",expected,fixture.getString("canaryToken").equals(traffic.optString("canary")));if(expected)assertTrue(traffic.getBoolean("dnsBlocked"));NativeVpn.disconnectAll(c);waitOff();result.put(new JSONObject().put("mode",policy[0]).put("probeRouted",expected).put("passed",true));
   }
  }finally{NativeVpn.disconnectAll(c);waitOff();new File(c.getNoBackupFilesDir(),"app-routing.json").delete();new NativeProfileStore(c).remove(node.get("id"));}
  Files.write(new File(c.getFilesDir(),"app-routing-result.json").toPath(),result.toString().getBytes("UTF-8"));
 }
 @Test public void selectiveReinstallThroughAppKeepsSharedDnsAndConnectsTwice()throws Exception{
  JSONObject first=api("status");String filter=first.getJSONObject("filtering").getString("instance");String oldInstance=first.getString("instance");
  Gateway sibling=ServerProtocols.create(node,SingleProtocols.OPENVPN);try(Ssh ssh=new Ssh(node);InputStream b=c.getAssets().open("single_bundle.zip")){assertTrue(ssh.single(b,new JSONObject().put("action","status").put("protocol","openvpn")).getBoolean("running"));}
  ArrayList<Gateway> nodes=new ArrayList<>(Arrays.asList(node,sibling));JSONObject inventory=new JSONObject().put("installed_protocols",new JSONArray().put("awg").put("openvpn"));for(Gateway g:nodes){g.data.put("probe",new JSONObject().put("inventory",new JSONObject(inventory.toString())));g.data.put("checkedAt",System.currentTimeMillis());}node.data.put("snapshot",first);new Vault(c).write(nodes);c.getSharedPreferences("rookstride-ui",0).edit().putBoolean("nativeBatteryAsked",true).commit();JSONArray evidence=new JSONArray();
  try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){
   screen.onActivity(a->{try{Field f=RookstrideActivity.class.getDeclaredField("gateways");f.setAccessible(true);f.set(a,nodes);}catch(Exception e){throw new AssertionError(e);}});
   for(int cycle=1;cycle<=2;cycle++){
    act(screen,"resetProtocol");long deadline=SystemClock.elapsedRealtime()+60000;while(SystemClock.elapsedRealtime()<deadline){try{onView(withText("Uninstall this protocol?")).check(matches(isDisplayed()));break;}catch(androidx.test.espresso.NoMatchingViewException|AssertionError e){Thread.sleep(300);}}
    onView(withText("I understand that affected users will lose access.")).perform(scrollTo(),click());onView(withText("Remove")).perform(click());
    deadline=SystemClock.elapsedRealtime()+60000;while(SystemClock.elapsedRealtime()<deadline&&ServerProtocols.installed(nodes,node).contains("awg"))Thread.sleep(300);assertFalse("Stale sibling inventory",ServerProtocols.installed(nodes,node).contains("awg"));assertTrue(ServerProtocols.installed(nodes,node).contains("openvpn"));
    act(screen,"protocolInstallation");deadline=SystemClock.elapsedRealtime()+480000;while(DeploymentService.current()==null&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(100);while(DeploymentService.active()&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(300);assertNotNull(DeploymentService.current());assertEquals("complete",DeploymentService.current().progress.state);
    JSONObject current=api("status");assertTrue(current.getBoolean("running"));assertEquals(filter,current.getJSONObject("filtering").getString("instance"));assertFalse(oldInstance.equals(current.getString("instance")));oldInstance=current.getString("instance");
    act(screen,"connectPhone");deadline=SystemClock.elapsedRealtime()+90000;while(SystemClock.elapsedRealtime()<deadline&&!NativeVpn.status(c,"awg").state.equals("connected")&&!NativeVpn.status(c,"awg").state.equals("failed"))Thread.sleep(300);assertEquals("connected",NativeVpn.status(c,"awg").state);
    Method probe=NativeEngineIntegrationTest.class.getDeclaredMethod("foreignProbe",Context.class,String.class);probe.setAccessible(true);JSONObject traffic=(JSONObject)probe.invoke(new NativeEngineIntegrationTest(),c,fixture.getString("canaryUrl"));assertTrue(traffic.getBoolean("vpnTransport"));assertTrue("VPN-only canary",fixture.getString("canaryToken").equals(traffic.getString("canary")));assertTrue("Expected egress",fixture.getString("expectedExit").equals(traffic.getString("ipv4Exit")));assertTrue(traffic.getBoolean("dnsBlocked"));
    current=api("status");assertTrue(current.getInt("recent_peers")>=1);assertTrue(current.getJSONArray("connections").length()>0);NativeVpn.disconnectAll(c);waitOff();String login="offline-cycle-"+cycle;api("add-user","login",login);api("remove-user","login",login);
    evidence.put(new JSONObject().put("cycle",cycle).put("app_reset_install_connect",true).put("shared_filter_identity_preserved",true).put("separate_uid_real_traffic_dns",true).put("disconnected_account_management",true).put("live_statistics",true));
   }
  }finally{NativeVpn.disconnectAll(c);waitOff();}
  Files.write(new File(c.getFilesDir(),"native-reinstall-result.json").toPath(),evidence.toString().getBytes("UTF-8"));
 }
}
